// Hand-written `@prisma/client` stub for the flowatlas fixture suite, shaped like the
// generated client: model access goes through a delegate property on `PrismaClient`
// (`prisma.order` -> `Prisma.OrderDelegate`), which is why the `prisma` descriptor needs
// `tableOverride: { kind: "receiver-prop" }` — the table name is the *property*, not a
// type argument.
//
// Two-segment scope on purpose: `resolveTypeOrigin` must report the package as
// `@prisma/client`, not `@prisma`.

export interface Order {
  id: string;
  userId: string;
  total: number;
  status: string;
}

export interface User {
  id: string;
  email: string;
}

